using System;

namespace StdbModule;

public static partial class GermanQuotes
{
    public static class FriedrichNietzsche
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Aus drei Anekdoten ist es möglich, das Bild eines Menschen zu geben.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Exstirpation des deutschen Geistes zugunsten des »deutschen Reiches«.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Der Wahrheit dienen wenige in Wahrheit, weil nur wenige den reinen Willen haben gerecht zu sein und selbst von diesen wieder die wenigsten die Kraft, gerecht sein zu können.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Copien. — Nicht selten begegnet man Copien bedeutender Menschen; und den Meisten gefallen, wie bei Gemälden, so auch hier, die Copien besser als die Originale.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Alle guten Dinge haben etwas Lässiges und liegen wie Kühe auf der Wiese.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Auch der vernünftigste Mensch bedarf von Zeit zu Zeit wieder der Natur, das heißt seiner ''unlogischen'' Grundstellung zu allen Dingen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Das Halbwissen ist siegreicher, als das Ganzwissen: es kennt die Dinge einfacher, als sie sind, und macht daher seine Meinung fasslicher und überzeugender.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Das Publikum verwechselt leicht den, welcher im Trüben fischt, mit dem, welcher aus der Tiefe schöpft.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Das Vollkommene soll nicht geworden sein. - Wir sind gewöhnt, bei allem Vollkommenen die Frage nach dem Werden zu unterlassen: sondern uns des Gegenwärtigen zu freuen, wie als ob es auf einen Zauberschlag aus dem Boden aufgestiegen sei.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Den Stil verbessern - das heißt den Gedanken verbessern, und gar nichts weiter! - Wer dies nicht sofort zugibt, ist auch nie davon zu überzeugen!", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Der Asket macht aus der Tugend eine Not.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Der Gewissensbiss ist, wie der Biss des Hundes gegen einen Stein, eine Dummheit.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Der Witz ist das Epigramm auf den Tod eines Gefühls.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Dicht neben dem Wehe der Welt, und oft auf seinem vulkanischen Boden, hat der Mensch seine kleinen Gärten des Glücks angelegt.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Die demokratischen Einrichtungen sind Quarantäne-Anstalten gegen die alte Pest tyrannenhafter Gelüste: als solche sehr nützlich und sehr langweilig.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Die Forderung, geliebt zu werden, ist die größte der Anmaßung.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Die Mutter der Ausschweifung ist nicht die Freude, sondern die Freudlosigkeit.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wenn der Mensch vor Lachen wiehert, übertrifft er alle Tiere durch seine Gemeinheit.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Die Scham existiert überall, wo es ein »Mysterium« gibt.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Die Tätigen rollen, wie der Stein rollt, gemäß der Dummheit der Mechanik.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ein Beruf macht gedankenlos; darin liegt sein größter Segen. Denn er ist eine Schutzwehr, hinter welche man sich, wenn Bedenken und Sorgen allgemeiner Art Einen anfallen, erlaubtermaßen zurückziehen kann.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Etwas Kurz-Gesagtes kann die Frucht und Ernte von vielem Lang-Gedachten sein.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ich rede von der Demokratie als von etwas Kommendem. Das, was schon jetzt so heißt, unterscheidet sich von den älteren Regierungsformen allein dadurch, dass es mit ''neuen Pferden'' fährt: Die Straßen sind noch die alten, und die Räder sind auch noch die alten.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Im Kampf mit der Dummheit werden die billigsten und sanftesten Menschen zuletzt brutal.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Jedes Wort ist ein Vorurteil.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Menschen, welche man nicht leiden kann, sucht man sich zu verdächtigen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Neid und Eifersucht sind die Schamteile der menschlichen Seele.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ohne die blinden Schüler ist noch nie der Einfluss eines Mannes und seines Werkes groß geworden. Einer Erkenntnis zum Siege verhelfen heißt oft nur: sie so mit der Dummheit verschwistern, dass das Schwergewicht der letzteren auch den Sieg für die erstere erzwingt.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Tief denkende Menschen kommen sich im Verkehr mit anderen als Komödianten vor, weil sie sich da, um verstanden zu werden, immer erst eine Oberfläche anheucheln müssen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Überzeugungen sind gefährlichere Feinde der Wahrheit als Lügen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Viele sind hartnäckig in Bezug auf den einmal eingeschlagenen Weg, wenige in Bezug auf das Ziel.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Von der Tragik begehrt das Volk eigentlich nicht mehr, als recht gerührt zu werden, um sich einmal ausweinen zu können.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Weg mit den bis zum Überdruss verbrauchten Wörtern Optimismus und Pessimismus! Denn der Anlass, sie zu gebrauchen, fehlt von Tag zu Tage mehr: nur die Schwätzer haben sie jetzt noch so unumgänglich nötig.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wer von seinem Tag nicht zwei Drittel für sich hat, ist ein Sklave.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Zu den Dingen, welche einen Denker in Verzweiflung bringen können, gehört die Erkenntnis, dass das Unlogische für den Menschen nötig ist, und dass aus dem Unlogischen vieles Gutes entsteht.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Das beste Mittel, jeden Tag gut zu beginnen, ist: beim Erwachen daran zu denken, ob man nicht wenigstens einem Menschen eine Freude machen könne.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Die beiden gegnerischen Parteien, die socialistische und die nationale - oder wie die Namen in den verschiedenen Ländern Europa's lauten mögen - sind einander würdig: Neid und Faulheit sind die bewegenden Mächte in ihnen beiden.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Aus den Leidenschaften wachsen die Meinungen; die Trägheit des Geistes lässt diese zu Ueberzeugungen erstarren.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Die Lehre von der Freiheit des Willens ist eine Erfindung herrschender Stände.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Auch große Geister haben nur ihre fünf Finger breite ''Erfahrung'', - gleich daneben hört ihr Nachdenken auf: und es beginnt ihr unendlicher leerer Raum und ihre Dummheit.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "»Die Regel ist mir immer interessanter, als die Ausnahme« - wer so empfindet, der ist in der Erkenntnis weit voraus und gehört zu den Eingeweihten.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ein Deutscher ist großer Dinge fähig, aber es ist unwahrscheinlich, dass er sie tut: Denn er gehorcht, ''wo er kann'', wie dies einem an sich trägen Geiste wohl tut.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Geschichte handelt fast nur von [...] schlechten Menschen, die später gutgesprochen worden sind.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Meister und Schüler - Zur Humanität eines Meisters gehört, seine Schüler vor sich zu warnen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Blas dich nicht auf: sonst bringet dich // Zum Platzen schon ein kleiner Stich.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Verhasst ist mir das Folgen und das Führen. // Gehorchen? Nein! Und aber nein — Regieren!", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Der Gedanke des sterbenden Nero: qualis artifex pereo! war auch der Gedanke des sterbenden Augustus: Histrionen-Eitelkeit! Histrionen-Schwatzhaftigkeit! Und recht das Gegenstück zum sterbenden Sokrates!", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ich wohne in meinem eignen Haus, // Hab Niemandem nie nichts nachgemacht // Und - lachte noch jeden Meister aus, // Der nicht sich selber ausgelacht.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Kein Sieger glaubt an den Zufall.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Die mystischen Erklärungen gelten für tief; die Wahrheit ist, dass sie noch nicht einmal oberflächlich sind.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Glattes Eis // Ein Paradeis // Für Den, der gut zu tanzen weiss.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Gott ist todt! Gott bleibt todt! Und wir haben ihn getödtet! Wie trösten wir uns, die Mörder aller Mörder?", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Mitleid ist das angenehmste Gefühl bei Solchen, welche wenig stolz sind und keine Aussicht auf große Eroberungen haben: für sie ist die leichte Beute - und das ist jeder Leidende - etwas Entzückendes. Man rühmt das Mitleid als die Tugend der Freudenmädchen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Nichts theilen wir so gern an Andere mit, als das Siegel der Verschwiegenheit - samt dem, was darunter ist.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wer sich tief weiss, bemüht sich um Klarheit; wer der Menge tief scheinen möchte, bemüht sich um Dunkelheit.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Gedanken sind die Schatten unserer Empfindungen - immer dunkler, leerer, einfacher als diese.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Dass ihr verachtetet, ihr höheren Menschen, das macht mich hoffen. Die großen Verachtenden nämlich sind die großen Verehrenden.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Der Mensch ist ein Seil, geknüpft zwischen Tier und Übermensch - ein Seil über einem Abgrunde.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Du gehst zu Frauen? Vergiss die Peitsche nicht!", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ein wenig Weisheit ist schon möglich; aber diese selige Sicherheit fand ich an allen Dingen: dass sie lieber noch auf den Füßen des Zufalls - tanzen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Es gibt einen alten Wahn, der heißt Gut und Böse. Um Wahrsager und Sterndeuter drehte sich bisher das Rad dieses Wahns.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Es ist wahr: Wir lieben das Leben, nicht, weil wir ans Leben, sondern ans Lieben gewöhnt sind. Es ist immer etwas Wahnsinn in der Liebe. Es ist aber auch immer etwas Vernunft im Wahnsinn.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Gedanken, die mit Taubenf  üßen kommen, lenken die Welt.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Gegen das Kleine stachlicht zu sein, dünkt mich eine Weisheit für Igel.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Gewissensbisse erziehn zum Beißen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Habt ihr Mut, oh meine Brüder? Seid ihr herzhaft? ''Nicht'' Mut vor Zeugen, sondern Einsiedler- und Adler-Mut, dem auch kein Gott mehr zusieht?", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Hütet euch auch vor den Gelehrten! Die hassen euch: denn sie sind unfruchtbar! Sie haben kalte vertrocknete Augen, vor ihnen liegt jeder Vogel entfedert.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ich beschwöre euch, meine Brüder, ''bleibt der Erde treu'' und glaubt Denen nicht, welche euch von überirdischen Hoffnungen reden! Giftmischer sind es, ob sie es wissen oder nicht. Verächter des Lebens sind es, Absterbende und selber Vergiftete, deren die Erde müde ist: so mögen sie dahinfahren!", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ich sage euch: man muss noch Chaos in sich haben, um einen tanzenden Stern gebären zu können. Ich sage euch: ihr habt noch Chaos in euch.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ihr habt den Weg vom Wurme zum Menschen gemacht, und vieles ist in euch noch Wurm.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ihr habt mir zu grausame Augen und blickt lüstern nach Leidenden. Hat sich nicht nur eure Wollust verkleidet und heißt sich Mitleiden?", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Macht wollen sie und zuerst das Brecheisen der Macht, viel Geld - diese Unvermögenden!", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Nicht durch Zorn, sondern durch Lachen tötet man.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Nicht nur fort sollst du dich pflanzen, sondern hinauf! Dazu helfe dir der Garten der Ehe!", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "»Nichts ist wahr, alles ist erlaubt« sprach ich mir zu.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Nicht, wenn die Wahrheit schmutzig ist, sondern wenn sie seicht ist, steigt der Erkennende ungern in ihr Wasser.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Staat heißt das kälteste aller kalten Ungeheuer. Kalt lügt es auch; und diese Lüge kriecht aus seinem Munde: »Ich, der Staat, bin das Volk.«", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Und alle Götter lachten damals und wackelten auf ihren Stühlen und riefen: »Ist das nicht eben Göttlichkeit, dass es Götter, aber keinen Gott giebt?« Wer Ohren hat, der höre.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Und hüte dich auch vor den Anfällen deiner Liebe! Zu schnell streckt der Einsame dem die Hand entgegen, der ihm begegnet.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Und wer unter Menschen nicht verschmachten will, muss lernen, aus allen Gläsern zu trinken; und wer unter Menschen rein bleiben will, muss verstehn, sich auch mit schmutzigem Wasser zu waschen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wahrlich, der Sonne gleich liebe ich das Leben und alle tiefen Meere. Und dies heißt mir Erkenntnis: alles Tiefe soll hinauf - zu meiner Höhe!", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Weh spricht: Vergeh! // Doch alle Lust will Ewigkeit, // will tiefe, tiefe Ewigkeit.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wer ihn als einen Gott der Liebe preist, denkt nicht hoch genug von der Liebe selber.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wenn es Götter gäbe, wie hielte ich's aus, kein Gott zu sein! Also gibt es keine Götter.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Trachte ich denn nach Glücke? Ich trachte nach meinem Werke!", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Das Christentum gab dem Eros Gift zu trinken - er starb zwar nicht daran, aber entartete, zum Laster.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Der eine sucht einen Geburtshelfer für seine Gedanken, der andre einen, dem er helfen kann: so entsteht ein gutes Gespräch.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Der Irrsinn ist bei Einzelnen etwas seltenes - aber bei Gruppen, Parteien, Völkern, Zeiten die Regel.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "»Die Erkenntnis um ihrer selbst willen« - das ist der letzte Fallstrick, den die Moral legt: damit verwickelt man sich noch einmal völlig in sie.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Die Neigung, sich herabzusetzen, sich bestehlen, belügen und ausbeuten zu lassen, könnte die Scham eines Gottes unter Menschen sein.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Die Zeit für kleine Politik ist vorbei: schon das nächste Jahrhundert bringt den Kampf um die Erd-Herrschaft, - den Zwang zur großen Politik.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Es giebt gar keine moralischen Phänomene, sondern nur eine moralische Ausdeutung von Phänomenen....", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Es kennzeichnet die Deutschen, dass bei ihnen die Frage »was ist deutsch?« niemals ausstirbt.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Grad und Art der Geschlechtlichkeit eines Menschen reicht bis in den letzten Gipfel seines Geistes hinauf.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Kurz, hier wie überall, Vorsicht mit ''überflüssigen'' teleologischen Principien!", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Man lügt wohl mit dem Munde, aber mit dem Maule, das man dabei macht, sagt man doch noch die Wahrheit.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Man soll nicht in Kirchen gehn, wenn man reine Luft atmen will.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Nicht ihre Menschenliebe, sondern die Ohnmacht ihrer Menschenliebe hindert die Christen von heute, uns - zu verbrennen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Reife des Mannes: das heißt den Ernst wiedergefunden haben, den man als Kind hatte, beim Spiel.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Der Weise als Astronom. - Solange du noch die Sterne fühlst als ein »Über-dir«, fehlt dir noch der Blick des Erkennenden.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Soll das Band nicht reißen, - mußt du erst drauf beißen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Viel von sich reden kann auch ein Mittel sein, sich zu verbergen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Was aus Liebe getan wird, geschieht immer jenseits von Gut und Böse.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wenn das Haus brennt, vergisst man sogar das Mittagessen. - Ja: aber man holt es auf der Asche nach.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wenn der Entschluss einmal gefasst ist, das Ohr auch für den besten Gegengrund zu schließen: Zeichen des starken Charakters. Also ein gelegentlicher Wille zur Dummheit.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wer auf dem Scheiterhaufen noch frohlockt, triumphiert nicht über den Schmerz, sondern darüber, keinen Schmerz zu fühlen, wo er ihn erwartete. Ein Gleichnis.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wer mit Ungeheuern kämpft, mag zusehn, dass er nicht dabei zum Ungeheuer wird. Und wenn du lange in einen Abgrund blickst, blickt der Abgrund auch in dich hinein.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wer sich selbst verachtet, achtet sich doch immer noch dabei als Verächter.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wer das Hohe eines Menschen nicht sehen ''will'', blickt um so schärfer nach dem, was niedrig und Vordergrund an ihm ist — und verräth sich selbst damit.-", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ist das Leben nicht hundert Mal zu kurz, sich in ihm — zu langweilen?", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Damit, dass man nach den Anfängen sucht, wird man Krebs. Der Historiker sieht rückwärts, endlich glaubt er auch rückwärts.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Damit es Kunst giebt, damit es irgend ein ästhetisches Thun und Schauen giebt, dazu ist eine physiologische Vorbedingung unumgänglich: der Rausch.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Dante: oder die Hyäne, die in Gräbern dichtet.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Der Aphorismus, die Sentenz, in denen ich als der Erste unter Deutschen Meister bin, sind die Formen der »Ewigkeit«; mein Ehrgeiz ist, in zehn Sätzen zu sagen, was jeder andre in einem Buche sagt - was jeder andre in einem Buche ''nicht'' sagt.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Der getretene Wurm krümmt sich. So ist es klug. Er verringert damit die Wahrscheinlichkeit, von neuem getreten zu werden. In der Sprache der Moral: Demut.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Emerson hat jene gütige und geistreiche Heiterkeit, welche allen Ernst entmutigt.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Hat man sein ''warum''? des Lebens, so verträgt man sich fast mit jedem ''wie''? - Der Mensch strebt ''nicht'' nach Glück; nur der Engländer tut das.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ich fürchte, wir werden Gott nicht los, weil wir noch an die Grammatik ''glauben'' [...]", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ich misstraue allen Systematikern und gehe ihnen aus dem Weg. Der Wille zum System ist ein Mangel an Rechtschaffenheit.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ohne Musik wäre das Leben ein Irrtum.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Schiller: oder der Moral-Trompeter von Säckingen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Was? du suchst? du möchtest dich verzehnfachen, verhundertfachen? du suchst Anhänger? - Suche ''Nullen''!", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Was mich nicht umbringt, macht mich stärker.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wie? ist der Mensch nur ein Fehlgriff Gottes? Oder Gott nur ein Fehlgriff des Menschen?", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Die Schwachen und Missratnen sollen zu Grunde gehen: erster Satz ''unserer'' Menschenliebe. Und man soll ihnen noch dazu helfen.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Das Weib war der ''zweite'' Fehlgriff Gottes […] - das weiß jeder Priester.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Es steht niemandem frei, Christ zu werden: man wird nicht zum Christentum »bekehrt«, - man muss krank genug dazu sein.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "»Glaube« heißt Nicht-wissen-wollen, was wahr ist.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Unrecht liegt niemals in ungleichen Rechten, es liegt im Anspruch auf »gleiche« Rechte.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ich ''verurteile'' das Christentum, ich erhebe gegen die christliche Kirche die furchtbarste aller Anklagen, die je ein Ankläger in den Mund genommen hat. Sie ist mir die höchste aller denkbaren Korruptionen, sie hat den Willen zur letzten auch nur möglichen Korruption gehabt.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Man muss der Menschheit überlegen sein durch Kraft, durch Höhe der Seele, - durch Verachtung...", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Die gewöhnlichste Lüge ist die, mit der man sich selbst belügt; das Belügen andrer ist relativ der Ausnahmefall.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Alle Vorurteile kommen aus den Eingeweiden.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wenn man von einem unerträglichen Druck loskommen will, so hat man Haschisch nötig. Wohlan, ich hatte Wagner nötig.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ich selbst bin immer noch Pole genug, um gegen Chopin den Rest der Musik hinzugeben.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "»Emanzipation des Weibes« – das ist der Instinkthaß des mißratenen, das heißt gebäruntüchtigen Weibes gegen das wohlgeratene.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ich bin kein Mensch, ich bin Dynamit.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Hat man mich verstanden?", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Die Romantiker ermangeln des Instinktes: die Kunstwahngebilde reizen sie nicht zur That, sie verharren im Reizungszustande.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ein Staatsmann zertheilt die Menschheit in zwei Gattungen, erstens Werkzeuge, zweitens Feinde. Eigentlich giebt es also für ihn nur Eine Gattung von Menschen: Feinde.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "In Wahrheit heißt etwas wollen, ein Experiment machen, um zu erfahren, was wir ''können''; darüber kann uns allein der Erfolg oder Misserfolg belehren.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Der Mensch entdeckt zuletzt nicht die Welt, sondern seine Tastorgane und Fühlhörner und deren Gesetze - aber ist deren Existenz nicht schon ein genügender Beweis für die Realität? Ich denke, der Spiegel beweist die Dinge.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Mit ihm verglichen, war mir selbst Beethoven ein halbbarbarisches Wesen, dessen große Seele schlecht erzogen wurde, so dass sie das Erhabene vom Abenteuerlichen, das Schlichte vom Geringen und Abgeschmackten nie recht zu unterscheiden gelernt hat.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Indem wir fortwährend uns üben, es mit allerlei Mitmenschen auszuhalten, üben wir uns unbewußt darin, uns selber auszuhalten: was eigentlich die unbegreiflichste Leistung des Menschen ist.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "In der Flamme der Eifersucht wendet man gleich dem Skorpione den vergifteten Stachel gegen sich selber - doch ohne den Erfolg des Skorpions.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ein labyrinthischer Mensch sucht niemals die Wahrheit, sondern einzig seine Ariadne - was er uns auch sagen möge.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Wir haben also als Missverständnis: […] eine kirchliche Ordnung, mit Priesterschaft, Theologie, Cultus, Sakramenten; kurz, alles das, was Jesus von Nazareth bekämpft hatte.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Jesus ist das Gegenstück eines Genies: Er ist ein Idiot.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Erziehung: wesentlich das Mittel, die Ausnahme zu ruiniren zu Gunsten der Regel. Bildung: wesentlich das Mittel, den Geschmack gegen die Ausnahme zu richten zu Gunsten des Mittleren.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Ich fand die ganze liebe deutsche Bestie gegen mich anspringend - ich bin ihr nämlich durchaus nicht mehr »moralisch« genug.«", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Es ist ''nicht'' nötig, nicht einmal ''erwünscht'', Partei für mich zu nehmen: im Gegenteil, eine Dosis Neugierde, wie vor einem fremden Gewächs, mit einem ironischen Widerstande, schiene mir eine unvergleichlich ''intelligentere'' Stellung zu mir.", Author = "Friedrich Nietzsche" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Nietzsche", Text = "Lieber Herr Professor, zuletzt wäre ich sehr viel lieber Basler Professor als Gott; aber ich habe es nicht gewagt, meinen Privat-Egoismus so weit zu treiben, um seinetwegen die Schaffung der Welt zu unterlassen. Sie sehen, man muß Opfer bringen, wie und wo man lebt.", Author = "Friedrich Nietzsche" },
        };
    }
}